/* ---------- translation watch: one source, shown in stations and in its own scroll ---------- */
const KIND = {mis:'Mistranslation', var:'Textual variant', com:'Common mistake', deb:'Debated', nu:'Lost nuance'};
const WORDS = {
title:{ref:'The title', kind:'com', title:'Revelation, not "Revelations"', greek:'Ἀποκάλυψις Ἰωάννου (Apokalypsis Iōannou)',
  body:`The oldest manuscripts call the book "the Apocalypse of John." <i>Apokalypsis</i> means an unveiling, like pulling a cover off something. It is one unveiling, singular. The book's own first words call it "the revelation of Jesus Christ" (1:1). It is first about who Jesus is, and only then about events.`},
signs:{ref:'1:1', kind:'nu', title:'"Signified": shown in signs', greek:'ἐσήμανεν (esēmanen), from σημεῖον (sēmeion), "sign"',
  body:`The KJV's "signified" is exact. God "sign-ified" the message, meaning he showed it by signs. Some modern versions say "made it known" (ESV, NIV). That is correct, but it loses the hint. On line one, the book tells you it speaks in pictures.`},
soon:{ref:'1:1; 1:3; 22:6–20', kind:'deb', title:'"Shortly" and "soon"', greek:'ἐν τάχει (en tachei); ταχύ (tachy); ὁ καιρὸς ἐγγύς (ho kairos engys)',
  body:`<i>En tachei</i> and <i>tachy</i> can mean "soon" or "quickly." Preterists read "soon for the first readers." Many futurists read "swiftly, once it starts," or "soon on God's clock" (2 Peter 3:8). "The time is near" (1:3; 22:10) is harder to stretch, and every view has to explain it.`},
land:{ref:'1:7', kind:'deb', title:'"All kindreds of the earth," or of the land?', greek:'πᾶσαι αἱ φυλαὶ τῆς γῆς (pasai hai phylai tēs gēs)',
  body:`<i>Gē</i> means both "earth" and "land." The verse quotes Zechariah 12:10–12, where the mourners are the families of Israel. Preterists read "all the tribes of the land" and see first-century Judea. Futurists read "all the peoples of the earth" and see a worldwide return. Both are possible Greek.`},
lordsday:{ref:'1:10', kind:'com', title:'"The Lord’s day" is not "the Day of the Lord"', greek:'ἐν τῇ κυριακῇ ἡμέρᾳ (en tē kyriakē hēmera)',
  body:`<i>Kyriakē</i> is an adjective: "the Lord's." Early Christian writers used it for Sunday, the day of the resurrection (Didache 14; Ignatius, <i>To the Magnesians</i> 9). A few readers take it as "the Day of the Lord," the end times. Greek writes that phrase differently: <i>hēmera kyriou</i> (1 Thessalonians 5:2).`},
angels:{ref:'1:20', kind:'nu', title:'"Angels" of the churches', greek:'ἄγγελοι (angeloi)',
  body:`<i>Angelos</i> simply means "messenger." The "angels of the seven churches" may be guardian angels, or human leaders who read the letters aloud. Each letter scolds its "angel" for the church's sins, which some think fits a human pastor better.`},
seat:{ref:'2:13', kind:'nu', title:'"Satan’s seat" is a throne', greek:'ὁ θρόνος τοῦ Σατανᾶ (ho thronos tou Satana)',
  body:`KJV says "seat." The word is <i>thronos</i>, the same word Revelation uses over 40 times for God's throne. Pergamum had a giant altar of Zeus and was the first city in Asia with a temple to Rome and Augustus (29 BC). The picture is political: two thrones, and you must pick one.`},
lukewarm:{ref:'3:15–16', kind:'com', title:'Lukewarm does not mean "better cold than lukewarm"', greek:'ψυχρός (psychros, cold), ζεστός (zestos, hot), χλιαρός (chliaros, lukewarm)',
  body:`People often hear: "I'd rather you be cold toward God than lukewarm." The local setting points somewhere else. Hot springs at nearby Hierapolis were good for healing. Cold spring water at Colossae was good to drink. Laodicea's water came by aqueduct, warm and full of minerals, and it made people want to spit. Hot and cold are both good. Lukewarm means useless. (M. J. S. Rudwick and E. M. B. Green, <i>Expository Times</i>, 1958; Craig Koester.)`},
beasts4:{ref:'4:6–9', kind:'mis', title:'"Four beasts" around God’s throne', greek:'ζῷα (zōa, "living ones") vs θηρίον (thērion, "wild beast")',
  body:`The KJV calls the creatures by God's throne "four beasts." The Greek <i>zōa</i> means "living ones." The monster of chapter 13 is a different word, <i>thērion</i>. In 1611 "beast" meant any animal, so the KJV was not wrong for its day. Today it puts God's worshipers and God's enemies under one label. NKJV, ESV, NIV and NASB all say "living creatures."`},
lamb:{ref:'5:6', kind:'nu', title:'A little lamb, slaughtered', greek:'ἀρνίον ὡς ἐσφαγμένον (arnion hōs esphagmenon)',
  body:`<i>Arnion</i> is a small word, sometimes "little lamb." <i>Esphagmenon</i> means "slaughtered," a sacrifice word, stronger than "slain." The Lamb stands alive yet still bears the marks. It is the book's main name for Jesus: 29 uses, 28 of them for Christ. The one other use is the land beast, which has horns "like a lamb" (13:11).`},
penny:{ref:'6:6', kind:'mis', title:'"A measure of wheat for a penny"', greek:'χοῖνιξ σίτου δηναρίου (choinix sitou dēnariou)',
  body:`A <i>dēnarion</i> was a full day's pay for a worker (Matthew 20:2). A <i>choinix</i>, about a quart, was one person's daily ration. So the rider announces a whole day's wage for one person's bread: famine prices, many times the normal cost. "Penny" makes it sound cheap. NIV: "two pounds of wheat for a day's wages."`},
pale:{ref:'6:8', kind:'nu', title:'The "pale" horse is green', greek:'χλωρός (chlōros)',
  body:`<i>Chlōros</i> (the root of "chlorophyll") means pale green, the gray-green of a corpse. Revelation uses the same word for green grass in 8:7 and 9:4.`},
virgins:{ref:'14:4', kind:'deb', title:'Men who are "virgins"', greek:'παρθένοι (parthenoi)',
  body:`The 144,000 "were not defiled with women, for they are virgins." <i>Parthenos</i> is usually used of women but here describes men. Many scholars read it as the purity rule for soldiers in holy war (Deuteronomy 23:9–10; 1 Samuel 21:5), which fits the army-style census of chapter 7. Others read faithfulness with no idolatry, which the prophets call adultery. A few read literal celibacy.`},
time:{ref:'10:6', kind:'mis', title:'"Time no longer"', greek:'χρόνος οὐκέτι ἔσται (chronos ouketi estai)',
  body:`KJV: "that there should be time no longer." This has often been preached as "time itself will end and eternity begins." In context the angel is answering the martyrs' cry, "How long?" (6:10). <i>Chronos</i> here means a waiting period. NKJV, ESV, NIV and NASB: "There will be no more delay." The scene answers Daniel 12:7, where an angel swears how long the waiting will be.`},
kingdom:{ref:'11:15', kind:'var', title:'"Kingdoms" or "kingdom"?', greek:'ἡ βασιλεία (singular) vs αἱ βασιλεῖαι (plural, Textus Receptus)',
  body:`KJV: "The kingdoms of this world are become the kingdoms of our Lord." The oldest manuscripts have the singular: "The kingdom of the world has become the kingdom of our Lord and of his Christ." The world is pictured as one kingdom, the beast's, which changes hands.`},
rapture:{ref:'12:5 (and 4:1)', kind:'com', title:'Revelation never uses "rapture" for the church', greek:'ἡρπάσθη (hērpasthē), from ἁρπάζω (harpazō), "snatch up"',
  body:`"Rapture" comes from the Latin of 1 Thessalonians 4:17 (<i>rapiemur</i>, "we will be caught up"). Revelation uses <i>harpazō</i> only once, for the male child, Jesus, "caught up to God and to his throne" (12:5). Pre-tribulation readers find the church's rapture implied at 4:1, "Come up here." Those words are spoken to John alone. The same words are spoken again in 11:12, to the two witnesses after they rise from the dead.`},
antichrist:{ref:'whole book', kind:'com', title:'The word "antichrist" is not in Revelation', greek:'ἀντίχριστος (antichristos)',
  body:`It appears only in 1 John 2:18, 22; 4:3 and 2 John 7, where John says "many antichrists" have already come. Revelation's figures are "the beast" and "the false prophet." Linking them to Paul's "man of lawlessness" (2 Thessalonians 2) and Daniel's "little horn" (Daniel 7:8) is a reasonable step, but it is an interpretation, not a quote.`},
seven:{ref:'11:2–3; 12:6, 14; 13:5', kind:'com', title:'Revelation never says "seven years"', greek:'μῆνας τεσσεράκοντα δύο (42 months); ἡμέρας χιλίας διακοσίας ἑξήκοντα (1,260 days)',
  body:`Revelation names a 3½-year period in several ways: 42 months, 1,260 days, and "a time, times and half a time." The seven-year tribulation comes from joining these to the "one week" of Daniel 9:27. That can be argued, but the number seven is built from Daniel, not stated in Revelation.`},
inhand:{ref:'13:16', kind:'mis', title:'A mark "in" the right hand', greek:'χάραγμα ἐπὶ τῆς χειρὸς (charagma epi tēs cheiros)',
  body:`KJV: "to receive a mark in their right hand, or in their foreheads." The Greek <i>epi</i> means "on." The English "in" has fed ideas about implanted chips. <i>Charagma</i> was the word for a stamp: the emperor's image on a coin, or an official seal on a sales contract. The mark copies God's seal on the forehead (7:3; 14:1) and the command to bind God's word on the hand and forehead (Deuteronomy 6:8).`},
n616:{ref:'13:18', kind:'var', title:'666 or 616?', greek:'χξϛʹ (666) vs χιϛʹ (616)',
  body:`Most manuscripts read 666. But Papyrus 115 (third century, the oldest copy of this verse) and Codex Ephraemi (fifth century) read 616. Irenaeus, around AD 180, knew both and defended 666. In Hebrew letters, "Nero Caesar" spelled נרון קסר adds up to 666. Spelled the Latin way, נרו קסר, it adds up to 616. That fit is why many scholars think the first readers heard "Nero."`},
armageddon:{ref:'16:16', kind:'com', title:'Armageddon is a place name', greek:'Ἁρμαγεδών (Harmagedōn), from Hebrew har Megiddo, "mountain of Megiddo"',
  body:`It is not a word that means "the end of the world." NASB prints it "Har-Magedon." Oddly, Megiddo is a mound on a plain, not a mountain. Suggestions include nearby Mount Carmel, where Elijah faced the prophets of Baal, or a play on Hebrew <i>har mo'ed</i>, "mount of assembly," where the king of Babylon tried to set up his throne (Isaiah 14:13).`},
mystery:{ref:'17:5', kind:'deb', title:'Is "Mystery" part of her name?', greek:'ὄνομα γεγραμμένον, μυστήριον (onoma gegrammenon, mystērion)',
  body:`KJV prints "MYSTERY, BABYLON THE GREAT" all in capitals, as if "Mystery" is part of the name. The Greek can mean "a name written, a mystery," meaning a symbolic name (compare "symbolically called" in 11:8). ESV: "a name of mystery." It warns you not to look for a city that is literally named Babylon.`},
deeds:{ref:'19:8', kind:'mis', title:'"The righteousness of saints"', greek:'τὰ δικαιώματα τῶν ἁγίων (ta dikaiōmata tōn hagiōn)',
  body:`KJV: "the fine linen is the righteousness of saints." The Greek is plural: "the righteous acts of the saints" (NKJV, ESV, NIV). The verse also says the linen was "given" to the bride to wear (<i>edothē</i>). So it holds both together: a gift, and a life lived out.`},
millennium:{ref:'20:2–7', kind:'nu', title:'The thousand years: one chapter', greek:'χίλια ἔτη (chilia etē)',
  body:`The thousand years appear six times, all in Revelation 20, and nowhere else in the Bible as a reign. Every millennial view rests mostly on this one chapter, read alongside Old Testament promises such as Isaiah 11 and 65.`},
washrobes:{ref:'22:14', kind:'var', title:'"Do his commandments" or "wash their robes"?', greek:'πλύνοντες τὰς στολὰς αὐτῶν vs ποιοῦντες τὰς ἐντολὰς αὐτοῦ',
  body:`KJV: "Blessed are they that do his commandments." The oldest manuscripts: "Blessed are those who wash their robes." Written in capitals with no spaces, as scribes wrote, the two look alike: ΠΛΥΝΟΝΤΕΣΤΑΣΣΤΟΛΑΣ and ΠΟΙΟΥΝΤΕΣΤΑΣΕΝΤΟΛΑΣ. A tired copyist could slip. "Wash their robes" ties back to 7:14.`},
bookoflife:{ref:'22:19', kind:'mis', title:'"Book of life" should be "tree of life"', greek:'ἀπὸ τοῦ ξύλου τῆς ζωῆς (apo tou xylou tēs zōēs)',
  body:`KJV: "God shall take away his part out of the book of life." Almost every Greek manuscript says "tree of life." When Erasmus printed the first Greek New Testament in 1516, his only manuscript of Revelation was missing its last page (22:16–21). He translated those verses back into Greek from the Latin Vulgate, and some Latin copies read <i>libro</i> ("book") instead of <i>ligno</i> ("tree"). The slip passed into the Textus Receptus and the KJV.`}
};

/* ---------- the stations ---------- */
const STATIONS = [
{ id:'ch1', ch:[1], cart:'Revelation 1', title:'The Voice on Patmos', art:'patmos',
  sum:[`John is in exile on Patmos, a small island off the coast of modern Turkey, "because of the word of God." On "the Lord's day" he hears a voice like a trumpet. He turns and sees Jesus, shining, with hair white as wool, eyes like fire, and a sharp sword coming out of his mouth. Jesus holds seven stars and walks among seven gold lampstands. He explains the picture himself: the stars are the messengers of seven churches, and the lampstands are the churches.`,
       `The first verse tells you how to read everything that follows. God "signified" it: he showed it in signs. Expect pictures that stand for things.`],
  verse:{ref:'1:1', plain:`This is the unveiling of Jesus Christ. God gave it to him to show his servants what must happen soon. He made it known through signs, sending his angel to his servant John.`,
    kjv:`The Revelation of Jesus Christ, which God gave unto him, to shew unto his servants things which must shortly come to pass; and he sent and signified it by his angel unto his servant John.`,
    greek:`Ἀποκάλυψις Ἰησοῦ Χριστοῦ … ἃ δεῖ γενέσθαι ἐν τάχει, καὶ ἐσήμανεν`, gk:`apokalypsis = unveiling; esēmanen = "he showed by signs"`},
  lit:`Jesus really appeared to John in a vision, and John wrote down what he saw. Many literal readers use 1:19 as the book's outline: what John has seen (chapter 1), what is now (chapters 2–3), and what will come later (chapters 4–22).`,
  sym:`The portrait is built from Daniel 7 and 10 and is not meant as a physical description. White hair recalls the "Ancient of Days," God himself. The sword from his mouth is his word (Isaiah 49:2; Hebrews 4:12). Jesus walking among the lampstands means he is present with his churches.`,
  views:{P:`Written before AD 70. "Soon" means soon for the first readers. The "coming with the clouds" (1:7) is Christ's judgment on Jerusalem.`,
    H:`The book is a map of church history, from John's day to the return of Christ.`,
    F:`Chapters 1–3 are John's day. Most of what follows is still in the future.`,
    I:`The vision shows what is always true: Christ is present with his suffering people in every age.`},
  words:['signs','soon','land','lordsday','angels'],
  echoes:'Daniel 7:9–14 · Daniel 10:5–6 · Zechariah 12:10 · Exodus 19:6 · Isaiah 44:6'
},
{ id:'ch2', ch:[2,3], cart:'Revelation 2 – 3', title:'Seven Letters, Seven Churches', art:'map',
  caption:'Map drawn from the cities’ real locations. The red loop follows the letters’ order, a natural road circuit starting from the port nearest Patmos.',
  sum:[`Jesus dictates a letter to each of seven real churches in what is now western Turkey. Each letter has the same parts: a title of Jesus taken from chapter 1, "I know your works," praise or warning, "Whoever has ears, let them hear," and a promise "to the one who conquers."`,
       `<b>Ephesus</b> works hard but has lost its first love (2:4). <b>Smyrna</b> is poor and persecuted and gets no rebuke. <b>Pergamum</b> lives "where Satan's throne is" and tolerates compromise. <b>Thyatira</b> is loving but tolerates a false prophet called "Jezebel." <b>Sardis</b> has a reputation for being alive, but is dead. <b>Philadelphia</b> is weak but faithful and gets no rebuke. <b>Laodicea</b> is rich and lukewarm, and hears "I stand at the door and knock" (3:20).`],
  verse:{ref:'3:15–16', plain:`I know what you do. You are neither cold nor hot. I wish you were one or the other! But since you are lukewarm, I am about to spit you out of my mouth.`,
    kjv:`I know thy works, that thou art neither cold nor hot: I would thou wert cold or hot. So then because thou art lukewarm, and neither cold nor hot, I will spue thee out of my mouth.`,
    greek:`οὔτε ψυχρὸς εἶ οὔτε ζεστός … ὅτι χλιαρὸς εἶ`, gk:`psychros = cold, zestos = hot, chliaros = lukewarm`},
  lit:`These were seven real congregations with real problems around AD 95. Archaeology confirms local details. Laodicea was a banking city, a center for eye salve, and famous for black wool. That is exactly what 3:17–18 mocks: "you are poor, blind and naked."`,
  sym:`Seven means complete, so seven churches stand for the whole church. Every letter ends by speaking to "the churches," plural, so every church is meant to read all seven.`,
  views:{P:`Real churches under Roman and synagogue pressure before the Jewish war.`,
    H:`Seven ages of church history, from Ephesus (the apostles) to Laodicea (a rich, lukewarm modern church).`,
    F:`Real first-century churches. Many dispensationalists also see the seven "church ages," and note that the word "church" disappears after chapter 3.`,
    I:`Seven kinds of churches that exist in every generation.`},
  words:['lukewarm','seat'],
  spec:{key:'unrebuked', title:'The two churches with no rebuke are the two fighting over "who is Israel"',
    body:`Only Smyrna and Philadelphia get no correction. They are also the only two letters that mention "those who say they are Jews and are not" (2:9; 3:9). To Philadelphia Jesus promises, "I will make them come and bow down at your feet." That reverses Isaiah 60:14, where the nations bow at Israel's feet. My guess is that this pairing is deliberate. The churches that suffer for their claim to belong to Israel's Messiah are the ones Jesus fully affirms. Commentators note the Isaiah reversal. Linking it to the "no rebuke" pattern is my own observation. It matters for the Church and Israel question below, because it is one of the strongest single verses for the "one people" view, and it rarely comes up in popular debates.`},
  echoes:'Numbers 22–25 (Balaam) · 1 Kings 16–21 (Jezebel) · Isaiah 22:22 (key of David) · Isaiah 60:14 · Proverbs 3:12'
},
{ id:'ch4', ch:[4,5], cart:'Revelation 4 – 5', title:'The Throne and the Lamb', art:'throne',
  sum:[`A door opens in heaven, and a voice says, "Come up here." John sees God's throne with a rainbow like an emerald, 24 elders on thrones, and four living creatures full of eyes: one like a lion, one like an ox, one with a human face, and one like an eagle. Day and night they sing, "Holy, holy, holy."`,
       `God holds a scroll sealed with seven seals. No one is worthy to open it, and John weeps. An elder says, "The Lion of the tribe of Judah has won." John turns to see a lion, and sees a Lamb that looks like it has been slaughtered. The Lamb takes the scroll, and all creation worships.`,
       `This is the hinge of the whole book. John hears "Lion" and sees "Lamb." The power that rules history is a sacrifice.`],
  verse:{ref:'5:6', plain:`Then I saw a Lamb standing in the center of the throne, with the four living beings and the elders around it. It looked as if it had been slaughtered. It had seven horns and seven eyes, which are the seven Spirits of God sent out into all the earth.`,
    kjv:`And I beheld, and, lo, in the midst of the throne and of the four beasts, and in the midst of the elders, stood a Lamb as it had been slain, having seven horns and seven eyes, which are the seven Spirits of God sent forth into all the earth.`,
    greek:`ἀρνίον ἑστηκὸς ὡς ἐσφαγμένον`, gk:`arnion hestēkos hōs esphagmenon = a lamb standing, as slaughtered`},
  lit:`Heaven is a real place, and John was shown God's actual throne room. Many futurists read "Come up here" (4:1) as a picture of the church being raptured before the tribulation. That is why, they say, the church is not seen on earth after this.`,
  sym:`The scene borrows from Isaiah 6 and Ezekiel 1. The four creatures stand for all living creation: wild animals, tame animals, humans and birds. The 24 elders may be the 12 tribes plus the 12 apostles, God's one people from both covenants. Seven horns and seven eyes mean full power and full knowledge.`,
  views:{P:`The scroll is God's verdict on unfaithful Jerusalem. Some compare it to a certificate of divorce.`,
    H:`The scroll holds the history of the church to the end of the age.`,
    F:`The scroll is like the title deed to the earth. Opening it starts the future tribulation. The elders picture the church already in heaven.`,
    I:`Christ's death and resurrection is the key that unlocks the meaning of all history.`},
  words:['beasts4','lamb'],
  spec:{key:'camp', title:'The throne room is laid out like Israel’s camp',
    body:`In the wilderness, Israel camped in four groups around the tabernacle (Numbers 2). Old Jewish tradition gives each lead tribe a banner: Judah a lion, Reuben a man, Ephraim an ox, and Dan an eagle. Those are the four faces around God's throne. A few writers have linked the banners to Ezekiel 1. My extension is this: if the living creatures echo the camp banners, then heaven's worship is pictured as Israel camped around God. "The Lion of the tribe of Judah" (5:5) is named while the lion-faced creature stands nearby. The Lamb who appears is then the Passover lamb at the center of the camp. Caution: the banner tradition is written down later than Revelation, so this is a possible echo, not proof.`},
  echoes:'Isaiah 6:1–3 · Ezekiel 1:5–28 · Genesis 49:9–10 · Isaiah 53:7 · Exodus 12 · Daniel 7:10'
},
{ id:'ch6', ch:[6], cart:'Revelation 6 · 8:1', title:'Seven Seals and Four Riders', art:'horsemen',
  sum:[`The Lamb breaks the seals one at a time. The first four release four horsemen: a white horse whose rider has a bow and a crown, a red horse with a large sword, a black horse whose rider holds scales, and a pale green horse ridden by Death, with the Grave following.`,
       `The fifth seal shows martyrs under the altar crying, "How long?" They are told to rest a little longer. The sixth seal brings a great earthquake: the sun goes black, the moon turns red, and people hide in caves. The seventh seal brings silence in heaven for about half an hour (8:1).`],
  verse:{ref:'6:6', plain:`A quart of wheat for a full day's pay, and three quarts of barley for a day's pay. But don't harm the olive oil and the wine.`,
    kjv:`A measure of wheat for a penny, and three measures of barley for a penny; and see thou hurt not the oil and the wine.`,
    greek:`Χοῖνιξ σίτου δηναρίου`, gk:`choinix = one day's ration; dēnarion = one day's wage`},
  lit:`Real wars, famines and plagues, coming one after another. The sixth seal's signs in the sky are real events in nature.`,
  sym:`The horsemen come from Zechariah 1 and 6. They match what Jesus said in Matthew 24: wars, famines, earthquakes, "the beginning of birth pains." The four judgments in 6:8 (sword, famine, plague, wild beasts) are the exact list of Ezekiel 14:21. "The sun turned black" is the prophets' normal way of describing the fall of a kingdom (Isaiah 13:10 for Babylon; 34:4 for Edom).`,
  views:{P:`Rome's war on Judea, AD 66–70, including the terrible famine during the siege recorded by Josephus.`,
    H:`The Roman Empire's history from about AD 96 to 313, ending with the pagan empire's fall.`,
    F:`The first half of a future tribulation. The white rider is the Antichrist offering false peace.`,
    I:`These forces run through every age, and Christ holds the reins of each one.`},
  extra:`<p class="small muted">Who is the white rider? Three answers: Christ and the gospel going out (compare 19:11); a false Christ imitating him; or the Parthians, mounted archers from the east and the one empire Rome feared. Each horseman is "given" his power, so all four answer to the Lamb.</p>`,
  words:['penny','pale'],
  echoes:'Zechariah 1:8; 6:1–8 · Ezekiel 14:21 · Matthew 24:6–8 · Isaiah 34:4 · Hosea 10:8'
},
{ id:'ch7', ch:[7], cart:'Revelation 7', title:'The 144,000 and the Countless Crowd', art:'multitude',
  sum:[`Four angels hold back the four winds. Another angel seals God's servants on their foreheads: 144,000, which is 12,000 from each of the twelve tribes of Israel. Then John looks and sees a great crowd that no one could count, from every nation, tribe, people and language. They wear white robes, hold palm branches, and have "come out of the great tribulation."`,
       `The pattern from chapter 5 repeats. There John heard "Lion" and saw a Lamb. Here he hears a number from Israel and sees a crowd from every nation. Whether these are two groups or one group seen two ways is the center of the Church and Israel question.`],
  verse:{ref:'7:9', plain:`After this I looked, and there was a huge crowd that no one could count, from every nation, tribe, people and language. They stood in front of the throne and the Lamb, dressed in white robes, holding palm branches.`,
    kjv:`After this I beheld, and, lo, a great multitude, which no man could number, of all nations, and kindreds, and people, and tongues, stood before the throne, and before the Lamb, clothed with white robes, and palms in their hands;`,
    greek:`ὄχλος πολύς, ὃν ἀριθμῆσαι αὐτὸν οὐδεὶς ἐδύνατο`, gk:`ochlos polys = a great crowd; "which no one was able to count"`},
  lit:`The 144,000 are 144,000 Jewish believers, 12,000 from each tribe, sealed for protection and service during the tribulation. The crowd is a separate group: people from the nations saved during that time.`,
  sym:`144,000 is 12 × 12 × 1,000: the tribes times the apostles times a great number, meaning all of God's people. The list reads like a military census (Numbers 1), an army that wins by the Lamb's blood. The crowd "no one could count" fulfills God's promise that Abraham's family would be as many as the stars (Genesis 15:5).`,
  views:{P:`The 144,000 are Jewish Christians who escaped Jerusalem before AD 70. The early historian Eusebius says they fled to Pella.`,
    H:`The true church, sealed and kept during the barbarian invasions (the four winds).`,
    F:`A literal remnant of Israel, plus a great crowd of people saved during the tribulation.`,
    I:`The whole church, protected spiritually but not physically, as it passes through suffering.`},
  israel:`The tribe list is unusual. Judah is listed first, not Reuben the firstborn. Dan and Ephraim are missing. Both Joseph and his son Manasseh are listed, and Levi, normally given no land, is included. Dan and Ephraim are the two tribes linked to the golden calves (1 Kings 12:29), which may explain why they are left out.`,
  spec:{key:'dan', title:'Dan is missing here, but first in line at the end',
    body:`Dan is left out of the sealing in chapter 7. But in Ezekiel's vision of restored Israel, Dan is the very first tribe given land (Ezekiel 48:1) and has its own gate in the city (48:32). Revelation 21 openly borrows Ezekiel's city, with twelve gates named for the twelve tribes, and it never lists which tribes. I suspect Dan's absence in chapter 7 is a mark of judgment on idolatry for that period, not a final exclusion. The worst tribe still gets a gate. The early idea that the Antichrist comes from Dan (Irenaeus, <i>Against Heresies</i> 5.30) is old, but Revelation never says it.`},
  echoes:'Ezekiel 9:4 · Numbers 1–2 · Genesis 15:5 · Leviticus 23:40 (palms at Tabernacles) · Isaiah 49:10 · Isaiah 25:8'
},
{ id:'ch8', ch:[8,9], cart:'Revelation 8 – 9', title:'Seven Trumpets', art:'trumpets',
  sum:[`After the silence, seven angels receive trumpets. An angel offers incense with the prayers of God's people, then throws fire to the earth. The first four trumpets strike a third of the land, sea, rivers and sky: hail and fire mixed with blood, a burning mountain thrown into the sea, a star called Wormwood that poisons the water, and a darkened sun, moon and stars.`,
       `An eagle cries "Woe, woe, woe." The fifth trumpet opens the abyss. Locusts come out, shaped like war horses, with human faces, long hair, lions' teeth and scorpion tails. They hurt but cannot kill, for five months, and their king is Abaddon, "the Destroyer." The sixth trumpet releases four angels at the Euphrates and an army of 200 million riders. A third of humanity dies. Yet the rest "did not repent" (9:20–21).`],
  verse:{ref:'9:11', plain:`Their king was the angel of the abyss. His name in Hebrew is Abaddon, and in Greek it is Apollyon: the Destroyer.`,
    kjv:`And they had a king over them, which is the angel of the bottomless pit, whose name in the Hebrew tongue is Abaddon, but in the Greek tongue hath his name Apollyon.`,
    greek:`ὄνομα αὐτῷ Ἑβραϊστὶ Ἀβαδδών, καὶ ἐν τῇ Ἑλληνικῇ ὄνομα ἔχει Ἀπολλύων`, gk:`Abaddon = "destruction" (Job 26:6); Apollyōn = "Destroyer"`},
  lit:`Real future disasters. Some popular teachers have suggested the locusts are attack helicopters and the 200 million riders are a modern Asian army. Some point out that the name Chernobyl comes from a plant related to wormwood.`,
  sym:`The trumpets replay the plagues of Egypt: hail and fire (the 7th plague), water to blood (the 1st), darkness (the 9th), locusts (the 8th). God is leading a new Exodus. Only "a third" is struck, so these are warnings meant to bring people to repentance. The point of the chapter is its sad last line: they still did not repent.`,
  views:{P:`The Roman armies and the warring rebel factions inside Judea during the Jewish War.`,
    H:`The classic Protestant reading: trumpets 1–4 are the barbarian invasions of Rome; the locusts are the Arab armies of the 600s (with "five months" read as 150 years); the 6th trumpet is the Ottoman Turks, who took Constantinople in 1453.`,
    F:`Future judgments during the tribulation, many taken literally.`,
    I:`Natural and spiritual disasters through history, each one a call to turn back to God.`},
  echoes:'Exodus 7–10 · Joel 1–2 (locust army "like horses," "teeth of a lion") · Jeremiah 9:15 · Amos 5:7 · Job 26:6'
},
{ id:'ch10', ch:[10,11], cart:'Revelation 10 – 11', title:'The Little Scroll and the Two Witnesses', art:'witnesses',
  sum:[`A mighty angel stands with one foot on the sea and one on the land, holding a small open scroll. Seven thunders speak, but John is told to seal up what they said. The angel swears, "There will be no more delay." John eats the scroll. It tastes sweet but turns bitter in his stomach, and he is told to prophesy again.`,
       `John measures God's temple, but the outer court is given to the nations, who trample the holy city for 42 months. Two witnesses prophesy for 1,260 days. They breathe fire, shut the sky so it won't rain, and turn water into blood, like Elijah and Moses. The beast kills them, and their bodies lie in the street of "the great city, which is symbolically called Sodom and Egypt, where their Lord was crucified." After 3½ days they rise, hear "Come up here," and go up to heaven. The seventh trumpet sounds: "The kingdom of the world has become the kingdom of our Lord and of his Christ."`],
  verse:{ref:'11:3–4', plain:`I will give power to my two witnesses, and they will prophesy for 1,260 days, dressed in sackcloth. They are the two olive trees and the two lampstands that stand before the Lord of the earth.`,
    kjv:`And I will give power unto my two witnesses, and they shall prophesy a thousand two hundred and threescore days, clothed in sackcloth. These are the two olive trees, and the two candlesticks standing before the God of the earth.`,
    greek:`αἱ δύο ἐλαῖαι καὶ αἱ δύο λυχνίαι`, gk:`elaiai = olive trees; lychniai = lampstands, the same word used for the churches in 1:20`},
  lit:`A rebuilt temple will stand in Jerusalem. Two individual prophets will preach there, perhaps Moses and Elijah, or Enoch and Elijah, the two men who never died (an early church view). The whole world will watch their bodies, which some say points to modern media.`,
  sym:`The temple is God's people (1 Corinthians 3:16). Measuring it means protecting it. The two witnesses are called "two lampstands," and chapter 1 has already said lampstands are churches. So they picture the church's witness. There are two because the Law required two witnesses (Deuteronomy 19:15).`,
  views:{P:`The Jerusalem temple before AD 70. "The great city where their Lord was crucified" is Jerusalem. The 42 months match the Roman war, spring 67 to August 70.`,
    H:`The witnesses are the Old and New Testaments, or faithful groups such as the Waldensians. Some historicists linked their death and rising to the French Revolution's attack on the Bible.`,
    F:`Two prophets in a rebuilt Jerusalem temple during the tribulation.`,
    I:`The church's witness, suffering, and final vindication in every age.`},
  words:['time','kingdom','seven'],
  spec:{key:'olive', title:'The two witnesses as Israel and the church, standing side by side',
    body:`Three passages use olive trees for God's people. In Zechariah 4, two olive trees feed one lampstand: the king and the priest of restored Israel. In Romans 11, Paul pictures one olive tree with natural branches (Israel) and grafted branches (the nations). Revelation 11 has two olive trees and two lampstands. Seven lampstands meant the whole church in chapter 1. My speculation is that the two lampstands are the two branches of Paul's tree, believing Israel and the church from the nations, witnessing together as the "kingdom of priests" (1:6). That would explain why there are two, why they share one story of death and resurrection, and why they appear in Jerusalem. I have not seen this argued in the main commentaries, though someone may have suggested it.`},
  echoes:'Ezekiel 2:8–3:3 · Daniel 12:7 · Zechariah 4 · Ezekiel 40–42 · 1 Kings 17:1 · Exodus 7:17 · Daniel 7:25'
},
{ id:'ch12', ch:[12], cart:'Revelation 12', title:'The Woman, the Child and the Dragon', art:'woman',
  sum:[`A great sign appears in the sky: a woman clothed with the sun, the moon under her feet, and a crown of twelve stars. She is about to give birth. A huge red dragon with seven heads and ten horns sweeps a third of the stars down with its tail and waits to eat her child. She gives birth to a son who will "rule all the nations with an iron rod." The child is caught up to God and his throne. The woman flees into the wilderness, where God cares for her for 1,260 days.`,
       `War breaks out in heaven. Michael and his angels throw the dragon down. He is named plainly: "that ancient serpent called the Devil and Satan." A voice says, "They defeated him by the blood of the Lamb and by the word of their testimony." The dragon chases the woman, but she is given eagle's wings, and the earth swallows the flood he sends. So he goes to war against "the rest of her children."`,
       `This chapter steps behind the scenes. It shows the real enemy behind the beasts that come next.`],
  verse:{ref:'12:1', plain:`Then a great sign appeared in the sky: a woman dressed in the sun, with the moon under her feet and a crown of twelve stars on her head.`,
    kjv:`And there appeared a great wonder in heaven; a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars:`,
    greek:`σημεῖον μέγα ὤφθη ἐν τῷ οὐρανῷ`, gk:`sēmeion mega = a great sign (KJV "wonder")`},
  lit:`Some readers tie 12:1–2 to a real arrangement of stars in the constellation Virgo. Predictions built on this, such as the one for September 23, 2017, did not come true. Most literal readers still treat the woman as a symbol, because John calls her a "sign," and read her as national Israel.`,
  sym:`The woman is Israel. In Joseph's dream the sun, moon and stars are Jacob's family (Genesis 37:9). Israel gives birth to the Messiah. Later she is the faithful people of God, the church, protected in the wilderness. Christian tradition also sees Mary here, and Eve: the "ancient serpent" fights the woman's offspring, as promised in Genesis 3:15.`,
  views:{P:`Israel gives birth to the Messiah. The woman's flight is the Jerusalem church escaping before AD 70.`,
    H:`The true church in the wilderness during 1,260 years of persecution, often dated AD 538–1798.`,
    F:`The woman is national Israel, protected for the last 3½ years. Some suggest the hiding place is Petra.`,
    I:`The age-long war between God's people and Satan, from Eden to the end.`},
  extra:`<p class="small muted">The chapter states its time period two ways: 1,260 days (12:6) and "a time, times, and half a time" (12:14). Both describe the same stay in the wilderness, so the two phrases name one period.</p>`,
  words:['rapture'],
  spec:{key:'harpazo', title:'Revelation’s only "rapture" is the ascension of Jesus',
    body:`The verb Paul uses for believers being "caught up" (1 Thessalonians 4:17) appears once in Revelation: for the child in 12:5. In Revelation's story, the Son's being caught up to the throne is the event that throws the dragon out of heaven (12:7–10). My speculation: Revelation reframes the rapture question. The church's hope is pictured as following the Lamb's own path, "wherever he goes" (14:4): faithful witness, death, resurrection, then "Come up here," exactly the sequence of the two witnesses (11:7–12). If that is right, the book does not ask "will we escape before the trouble?" but "will we follow where he went?" This lands closest to post-tribulation and idealist readings, and it is my own synthesis.`},
  echoes:'Genesis 3:15 · Genesis 37:9 · Isaiah 66:7–8 · Psalm 2:9 · Daniel 10:13; 12:1 · Exodus 19:4 · Isaiah 27:1'
},
{ id:'ch13', ch:[13], cart:'Revelation 13', title:'The Two Beasts', art:'beasts',
  sum:[`The dragon stands on the seashore. A beast rises from the sea with ten horns wearing ten crowns, and seven heads with names that insult God. It looks like a leopard, with a bear's feet and a lion's mouth. One of its heads seems to have had a deadly wound that healed. The whole world is amazed and worships the dragon and the beast: "Who is like the beast? Who can fight it?" It rules for 42 months and makes war on God's people.`,
       `Then another beast rises from the earth. It has two horns like a lamb, but it speaks like a dragon. It works signs, calls fire from the sky, sets up a talking image of the first beast, and forces everyone to take a mark on the right hand or forehead in order to buy or sell. "Let the one who understands calculate the number of the beast, for it is a human number: 666."`,
       `The sea beast mixes all four of Daniel's beasts (lion, bear, leopard, ten horns) into one. It is every empire rolled together.`],
  verse:{ref:'13:18', plain:`This calls for wisdom. Whoever has understanding should figure out the number of the beast, because it is the number of a human being. Its number is 666.`,
    kjv:`Here is wisdom. Let him that hath understanding count the number of the beast: for it is the number of a man; and his number is Six hundred threescore and six.`,
    greek:`ἀριθμὸς γὰρ ἀνθρώπου ἐστίν`, gk:`"for it is a human number" or "the number of a man"`},
  lit:`A future world ruler, the Antichrist, will lead a global government. A false prophet will do real miracles. A literal mark, perhaps a chip, tattoo or digital ID, will be required to buy and sell. The healed wound may be a faked or real return from death.`,
  sym:`The sea beast is empire that demands worship: first-century Rome, and any state that claims to be God. The land beast is the religion and propaganda that serve it, like the priests of the emperor's cult in Asia. The mark copies God's seal (7:3) and the Shema's command to tie God's words "as a sign on your hand" and as "a band between your eyes" (Deuteronomy 6:8). What you think (forehead) and do (hand) shows whom you belong to.`,
  views:{P:`The beast is Nero; "Nero Caesar" in Hebrew letters adds to 666. The healed wound is Rome nearly collapsing in AD 69, the year of four emperors, and then recovering.`,
    H:`The Reformers' reading: the sea beast is the papacy and 42 months are 1,260 years. Luther, Calvin and the Westminster Confession (1646) called the pope the Antichrist. Most historicists today hold this more cautiously.`,
    F:`A future Antichrist and false prophet. The 42 months are the second half of Daniel's seventieth "week" (Daniel 9:27). The mark is literal.`,
    I:`Every age has its beasts: political power that wants worship, and the voices that make people give it.`},
  extra:`<p class="small muted">The beast's healed head is described with the same words as the Lamb: <span class="greek">ὡς ἐσφαγμένην</span>, "as slaughtered" (13:3; compare 5:6). The dragon, the beast and the false prophet copy the Father, the Son and the Spirit. Scholars call them the unholy trinity.</p>`,
  words:['inhand','n616','antichrist'],
  spec:{key:'solomon', title:'666 and the king who broke the king’s law',
    body:`The number 666 appears in one other place: the gold that came to Solomon in one year, 666 talents (1 Kings 10:14). That link is well known. What I rarely see noticed is the rest of the chapter. It goes on to list exactly what Deuteronomy 17:16–17 forbade Israel's king to pile up: gold, horses from Egypt, and (in chapter 11) many wives. It also describes Solomon controlling the horse and chariot trade (1 Kings 10:28–29). Revelation 13:17 is about controlling who can buy and sell. My speculation: "the number of a man" points to the moment a king of God's own people turned into a Pharaoh. The beast is not only a pagan threat from outside. It is what God's people become when they grasp at wealth, weapons and control.`},
  echoes:'Daniel 7:1–8 · Daniel 3 (the image: worship or die) · Deuteronomy 6:8 · Deuteronomy 13:1–3 · 1 Kings 10:14 · Matthew 24:24 · 2 Thessalonians 2:3–10'
},
{ id:'ch14', ch:[14], cart:'Revelation 14', title:'The Lamb on Mount Zion', art:'zion',
  sum:[`Right after the beasts, a contrast. The Lamb stands on Mount Zion with the 144,000. They have his name and his Father's name on their foreheads instead of the beast's mark. They sing a new song, "follow the Lamb wherever he goes," and are called firstfruits.`,
       `Three angels fly across the sky. The first carries "an eternal gospel" to every nation: "Fear God and worship the one who made heaven and earth." The second cries, "Fallen, fallen is Babylon the great!" The third warns that anyone who worships the beast will drink the wine of God's anger. A voice says, "Blessed are the dead who die in the Lord from now on." Then come two harvests: one like a son of man reaps the earth with a sickle, and an angel gathers grapes into the winepress of God's anger. Blood flows as high as a horse's bridle for 1,600 stadia, about 184 miles.`],
  verse:{ref:'14:13', plain:`Then I heard a voice from heaven say, "Write this: Blessed are the dead who die in the Lord from now on." "Yes," says the Spirit, "they will rest from their hard work, for what they have done goes with them."`,
    kjv:`And I heard a voice from heaven saying unto me, Write, Blessed are the dead which die in the Lord from henceforth: Yea, saith the Spirit, that they may rest from their labours; and their works do follow them.`,
    greek:`Μακάριοι οἱ νεκροὶ οἱ ἐν κυρίῳ ἀποθνῄσκοντες ἀπ᾿ ἄρτι`, gk:`makarioi = blessed; ap' arti = from now on`},
  lit:`The 144,000 of chapter 7 stand with Christ on the real Mount Zion in Jerusalem. The bloodshed is a real battle near Jerusalem. Some note that 1,600 stadia is roughly the length of the land of Israel.`,
  sym:`1,600 is 4 × 4 × 100. Four is the number of the earth's corners, so this means judgment that covers the whole world. The two harvests are different: grain is often the gathering of God's people (Matthew 13:30; John 4:35), while grapes and the winepress mean judgment (Isaiah 63:1–6; Joel 3:13).`,
  views:{P:`The harvest of Judea in AD 70.`,
    H:`The three angels picture later movements of world mission and reform. Seventh-day Adventists see the three angels' messages as their own calling since the 1840s.`,
    F:`Events just before Christ returns, in order.`,
    I:`The gospel goes out, empire falls, and history ends in a harvest.`},
  words:['virgins'],
  echoes:'Psalm 2:6 · Joel 2:32 · Jeremiah 2:3 · Daniel 7:13 · Joel 3:13 · Isaiah 63:1–6 · Isaiah 21:9'
},
{ id:'ch15', ch:[15,16], cart:'Revelation 15 – 16', title:'Seven Bowls and Armageddon', art:'bowls',
  sum:[`The people who defeated the beast stand by a sea of glass mixed with fire and sing "the song of Moses and the song of the Lamb." Seven angels come out of the temple with seven gold bowls full of God's anger. The temple fills with smoke, and no one can enter until the plagues are finished.`,
       `The bowls pour out on the earth (painful sores on those with the mark), the sea and the rivers (turned to blood), the sun (scorching heat), the beast's throne (darkness), and the Euphrates, which dries up for "the kings from the east." Three evil spirits like frogs come from the mouths of the dragon, the beast and the false prophet, and gather the kings of the world "to the place called in Hebrew Armageddon." The seventh bowl: "It is done!" The greatest earthquake ever splits the great city into three. Hailstones of about 100 pounds fall. Still, people curse God.`,
       `The trumpets struck a third. The bowls strike everything. The warnings are over.`],
  verse:{ref:'16:15–16', plain:`"Look, I am coming like a thief! Blessed is the one who stays awake and keeps their clothes on." Then the spirits gathered the kings to the place called in Hebrew Armageddon.`,
    kjv:`Behold, I come as a thief. Blessed is he that watcheth, and keepeth his garments… And he gathered them together into a place called in the Hebrew tongue Armageddon.`,
    greek:`εἰς τὸν τόπον τὸν καλούμενον Ἑβραϊστὶ Ἁρμαγεδών`, gk:`Harmagedōn = Har Megiddo, "mountain of Megiddo"`},
  lit:`A final world war will gather in the Jezreel Valley near Megiddo in northern Israel. The Euphrates will literally dry up; some point to modern dams in Turkey as a sign.`,
  sym:`Megiddo was a famous battlefield. Deborah won there (Judges 5:19) and King Josiah died there (2 Kings 23:29). "Armageddon" stands for the final showdown between God and the powers of the world. Drying the Euphrates recalls how Cyrus diverted the river to capture Babylon (Herodotus 1.191), and the drying of the Red Sea and the Jordan.`,
  views:{P:`The end of the Roman siege. The "kings from the east" are the legions Titus brought from the Euphrates.`,
    H:`The sixth bowl is the slow drying up of the Ottoman Empire in the 1800s.`,
    F:`Future judgments at the end of the tribulation, ending in a literal campaign of Armageddon.`,
    I:`The last conflict of good and evil, shown in every crisis of history.`},
  words:['armageddon'],
  spec:{key:'frogs', title:'Frogs: the last trick the magicians could copy',
    body:`The bowls follow the plagues of Egypt closely: sores, blood, darkness, frogs, hail. The frogs are a curious detail. In Exodus, frogs were the last plague Pharaoh's magicians could copy (Exodus 8:7). At the next plague, gnats, they failed and said, "This is the finger of God" (8:18–19). In Revelation 16:13 the frogs come out of the mouths of the false prophet and his allies, the ones who do counterfeit signs (13:13–14). My speculation: the frogs mark the last moment the counterfeit still works. Right after them comes "It is done," and every imitation of God's power stops at once. I have not seen the Exodus 8 detail used this way.`},
  echoes:'Exodus 7–10 · Exodus 15 (the song of Moses) · Judges 5:19 · Zechariah 12:11 · Joel 3:2, 12 · Jeremiah 51:36 · Ezekiel 38–39'
},
{ id:'ch17', ch:[17,18], cart:'Revelation 17 – 18', title:'Babylon the Great', art:'babylon',
  sum:[`An angel shows John "the great prostitute who sits on many waters." She rides a scarlet beast with seven heads and ten horns. She wears purple and scarlet, gold, jewels and pearls, holds a gold cup full of filth, and is drunk on the blood of God's people. On her forehead is written "Babylon the Great, mother of prostitutes."`,
       `The angel explains. The seven heads are seven hills where she sits, and also seven kings: five have fallen, one is, and one is still to come. The ten horns are ten kings who will give their power to the beast for one hour, then turn on the woman and burn her. "The woman you saw is the great city that rules over the kings of the earth" (17:18).`,
       `Chapter 18 is a funeral song. "Fallen, fallen is Babylon the great!" "Come out of her, my people." Kings, merchants and sailors weep from far away over her lost trade. The cargo list ends with "slaves, that is, human souls" (18:13). Heaven rejoices.`],
  verse:{ref:'18:4', plain:`Then I heard another voice from heaven say, "Come out of her, my people, so that you won't share in her sins and won't receive her plagues."`,
    kjv:`And I heard another voice from heaven, saying, Come out of her, my people, that ye be not partakers of her sins, and that ye receive not of her plagues.`,
    greek:`Ἐξέλθατε ὁ λαός μου ἐξ αὐτῆς`, gk:`"Come out of her, my people" (from Jeremiah 51:45)`},
  lit:`A real future city: a rebuilt Babylon in Iraq (Saddam Hussein rebuilt parts of it in the 1980s), Rome, Jerusalem, or a world trade center. The prostitute is a future one-world false religion that the Antichrist uses and then destroys.`,
  sym:`Babylon destroyed the first temple in 586 BC. Early Christians used "Babylon" as a code name for Rome (1 Peter 5:13). Rome sat on seven hills, was the world's great port city, and ruled over kings. The prostitute is the seductive side of empire: money, luxury, trade and false worship. She is the opposite of the Bride in chapters 19–21. The book ends with two women and two cities, and you choose one.`,
  views:{P:`Split: either Rome (seven hills, emperors as heads) or Jerusalem, pictured as an unfaithful bride, as in Ezekiel 16, and called "the great city" in 11:8.`,
    H:`Papal Rome, in the Reformers' reading.`,
    F:`A future Babylon, as a city or a global system, plus an end-time false religion.`,
    I:`The world system of greed and false worship in every age, which will surely fall.`},
  extra:`<p class="small muted">Counting the seven kings is famously hard. It depends on whether you start with Julius Caesar or Augustus, and whether you count the three emperors who ruled briefly in AD 69. Different counts give different dates for the book, which is why the list has never settled the debate.</p>`,
  words:['mystery'],
  echoes:'Jeremiah 50–51 · Isaiah 47 · Ezekiel 26–27 (Tyre’s merchants and cargo list) · Ezekiel 16; 23 · Daniel 4:30 · 1 Peter 5:13'
},
{ id:'ch19', ch:[19], cart:'Revelation 19', title:'The Rider on the White Horse', art:'rider',
  sum:[`Heaven shouts "Hallelujah," the only place in the New Testament where the word appears, four times here. The wedding of the Lamb has come, and his bride is dressed in fine linen, bright and clean. John falls down to worship the angel and is told, "Don't! Worship God."`,
       `Heaven opens. A rider on a white horse is called Faithful and True. His eyes are like fire, he wears many crowns, and his robe is dipped in blood. His name is "The Word of God." The armies of heaven follow him on white horses, dressed in white linen, not armor. A sharp sword comes from his mouth. On his robe and thigh is written "King of kings and Lord of lords."`,
       `The beast and the kings gather for war. There is no description of a fight. The beast and the false prophet are captured and thrown alive into the lake of fire, and the rest are killed by the sword from the rider's mouth.`],
  verse:{ref:'19:11', plain:`Then I saw heaven opened, and there was a white horse. Its rider is called Faithful and True. He judges and makes war with justice.`,
    kjv:`And I saw heaven opened, and behold a white horse; and he that sat upon him was called Faithful and True, and in righteousness he doth judge and make war.`,
    greek:`καλούμενος πιστὸς καὶ ἀληθινός`, gk:`pistos kai alēthinos = faithful and true (the title from 3:14)`},
  lit:`The visible, physical return of Jesus to earth (Acts 1:11; Zechariah 14:4), defeating real armies gathered against him.`,
  sym:`Christ wins by his word (the sword from his mouth, Isaiah 11:4) and by his own sacrifice. His robe is bloody before any battle starts, which many read as his own blood. The war is announced but never fought, because it is over the moment he speaks. There are two suppers: the wedding supper of the Lamb, and "the great supper of God" for the birds.`,
  views:{P:`Most partial preterists see this as the future Second Coming. Full preterists see Christ's victory through the gospel after AD 70.`,
    H:`The Second Coming at the end of church history.`,
    F:`The Second Coming at the end of the seven-year tribulation, before the thousand years.`,
    I:`Christ's sure victory over evil, already won at the cross.`},
  words:['deeds'],
  echoes:'Isaiah 63:1–3 · Isaiah 11:4 · Psalm 2:9 · Ezekiel 39:17–20 · John 1:1 · Matthew 22:1–14 · Daniel 2:47'
},
{ id:'ch20', ch:[20], cart:'Revelation 20', title:'The Thousand Years', art:'millennium',
  sum:[`An angel with the key to the abyss and a great chain seizes the dragon, binds him for 1,000 years, and seals him in the pit "so he could not deceive the nations." John sees thrones. Those who were beheaded for their witness, and who did not worship the beast, "came to life and reigned with Christ for a thousand years. This is the first resurrection."`,
       `After 1,000 years Satan is released. He deceives the nations, called Gog and Magog, who surround "the camp of God's people and the beloved city." Fire from heaven consumes them, and the devil is thrown into the lake of fire. Then comes the great white throne. The dead, great and small, are judged by what they had done. Death and the Grave are thrown into the lake of fire, which is "the second death."`,
       `This chapter holds the biggest debate in the book. There are three main views of the thousand years.`],
  verse:{ref:'20:4', plain:`I saw thrones, and those seated on them were given authority to judge. I also saw the souls of those who had been beheaded for their witness to Jesus and for God's word. They came to life and reigned with Christ for a thousand years.`,
    kjv:`And I saw thrones, and they sat upon them, and judgment was given unto them: and I saw the souls of them that were beheaded for the witness of Jesus, and for the word of God… and they lived and reigned with Christ a thousand years.`,
    greek:`καὶ ἔζησαν καὶ ἐβασίλευσαν μετὰ τοῦ Χριστοῦ χίλια ἔτη`, gk:`ezēsan = they lived, or came to life; chilia etē = a thousand years`},
  lit:`<b>Premillennial:</b> Christ returns before a literal 1,000-year reign on earth, ruling from Jerusalem. Old Testament promises, like the wolf living with the lamb (Isaiah 11:6–9) and long lives (Isaiah 65:20), come true on this earth. There are two physical resurrections, 1,000 years apart.`,
  sym:`<b>Amillennial:</b> the 1,000 years is the present age, from Christ's first coming to his return. Satan was "bound" at the cross so the gospel can reach the nations (Matthew 12:29). The saints reign with Christ now. <b>Postmillennial:</b> the gospel will slowly win the world, bringing a long golden age before Christ returns. 1,000 is 10 × 10 × 10: a long, complete period.`,
  views:{P:`Most preterists are amillennial or postmillennial. The thousand years began with Christ's first coming or after AD 70.`,
    H:`Historicists have held all three positions. Many older Protestants were postmillennial, among them Jonathan Edwards.`,
    F:`Premillennial: a literal future reign on earth after the tribulation. Dispensationalists see promises to national Israel fulfilled here.`,
    I:`Amillennial: the present church age, seen from heaven's side. This was Augustine's view, and it is held in Catholic, Orthodox, Lutheran and many Reformed churches.`},
  extra:`<p class="small muted">A detail that matters for the debate: 16:14, 19:19 and 20:8 all speak of gathering the nations for "<i>the</i> battle" (<span class="greek">τὸν πόλεμον</span>), and 19:17–21 and 20:8–9 both borrow from Ezekiel 38–39. Amillennial readers say these are one battle told three times. Premillennial readers say they are two battles, 1,000 years apart, and point to Isaiah 24:21–22, where hostile powers are shut in a prison and punished "after many days."</p>`,
  words:['millennium'],
  israel:`"The camp of God's people and the beloved city" (20:9). Premillennial readers see Jerusalem restored as Israel's capital. Amillennial readers see the church, which Hebrews 12:22 already calls "the heavenly Jerusalem."`,
  echoes:'Ezekiel 38–39 · Daniel 7:9–10, 22 · Isaiah 24:21–22 · Matthew 12:29 · Isaiah 65:17–25 · Psalm 90:4'
},
{ id:'ch21', ch:[21,22], cart:'Revelation 21 – 22:5', title:'The New Jerusalem', art:'city',
  sum:[`John sees a new heaven and a new earth, "and the sea was no more." The holy city comes down out of heaven like a bride dressed for her husband. A loud voice says, "Look! God's home is now with people." He will wipe away every tear. There will be no more death, grief, crying or pain. "I am making everything new."`,
       `The city shines like jasper. Its twelve gates carry the names of the twelve tribes of Israel, and its twelve foundations carry the names of the twelve apostles. The angel measures it: a cube 12,000 stadia (about 1,400 miles) long, wide and high. Each gate is one pearl. The street is gold, clear as glass. There is no temple, because God and the Lamb are its temple, and no sun, because God's glory lights it. The gates are never shut.`,
       `A river of the water of life flows from the throne. The tree of life grows on both banks, bearing twelve kinds of fruit, and its leaves heal the nations. There is no more curse. "They will see his face, and his name will be on their foreheads."`],
  verse:{ref:'21:4', plain:`He will wipe every tear from their eyes. There will be no more death, or sadness, or crying, or pain, because the old order of things has passed away.`,
    kjv:`And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.`,
    greek:`ὁ θάνατος οὐκ ἔσται ἔτι`, gk:`"death will be no more" (the same phrase shape as "the sea was no more," 21:1)`},
  lit:`A real physical city, about 1,400 miles on each side and just as tall. Its base would cover much of the United States. Some think it is a cube, others a pyramid.`,
  sym:`The only cube in the Bible is the Most Holy Place, 20 × 20 × 20 cubits (1 Kings 6:20). The whole city has become the Holy of Holies, where everyone now lives in God's presence. The city is also the bride (21:9–10), so the city is the people. Its numbers are built from 12: Israel and the apostles together.`,
  views:{P:`The new-covenant people of God after the old order passed away in AD 70 (Hebrews 8:13), already real now and complete in the future.`,
    H:`The final, eternal state after history ends.`,
    F:`The eternal state after the millennium. Some think the city hovers over the earth during the thousand years.`,
    I:`The church's final destiny and its true identity even now.`},
  israel:`Twelve gates named for Israel's tribes and twelve foundations named for the apostles. Neither group replaces the other. Both are built into one city, and you enter through Israel's names and stand on the apostles'.`,
  spec:{key:'sea', title:'"No more sea": the barrier is gone',
    body:`The sea is where the beast came from (13:1), so its end means the end of chaos and evil. That reading is common. I would add a temple layer. Before God's throne there was "a sea of glass" (4:6; 15:2). Solomon's temple also had a huge bronze basin called "the Sea," where priests washed before they could serve (1 Kings 7:23; 2 Chronicles 4:6). In Revelation 4 the sea of glass stands between the throne and everyone else. In the new creation there is no sea and no temple, and the people see God's face. My speculation: "no more sea" also means no more barrier and no more need to be washed before you may come close. The washing has already happened ("they washed their robes," 7:14; 22:14).`},
  spec2:{key:'cherub', title:'The angel at Eden’s gate becomes twelve angels at open gates',
    body:`After the fall, God placed cherubim at the east of Eden with a flaming sword "to guard the way to the tree of life" (Genesis 3:24). In the New Jerusalem there are angels at the gates again, twelve of them (21:12), but the gates are never shut (21:25), and the tree of life is inside. Revelation 22:14 then blesses those who "may go in through the gates" to "the tree of life." My speculation: the angels at the gates are the cherub of Genesis 3 turned around, no longer guarding the way to the tree but standing beside open doors. Commentators often note the return of the tree of life. Pairing Eden's guard with the city's twelve gatekeepers is my own connection.`},
  echoes:'Isaiah 65:17; 66:22 · Isaiah 25:8 · Ezekiel 40–48 · Ezekiel 47:1–12 · Genesis 2–3 · Isaiah 60 · 1 Kings 6:20 · Exodus 28:17–21 · Exodus 33:20'
},
{ id:'ch22', ch:[22], cart:'Revelation 22:6 – 21', title:'Come, Lord Jesus', art:'omega',
  sum:[`"These words are trustworthy and true." Jesus says "I am coming soon" three times (22:7, 12, 20). John falls before the angel again and is told again, "Worship God." Unlike Daniel, who was told to seal his book (Daniel 12:4), John is told, "Do not seal up the words of this prophecy, because the time is near."`,
       `Jesus says, "I am the Alpha and the Omega, the First and the Last." "I am the root and descendant of David, the bright morning star." "The Spirit and the bride say, 'Come!'" A warning follows not to add to the book or take away from it. The last words are a promise and a prayer: "Yes, I am coming soon." "Amen. Come, Lord Jesus." Then a blessing: "The grace of the Lord Jesus be with all."`],
  verse:{ref:'22:20', plain:`The one who is testifying to these things says, "Yes, I am coming soon." Amen! Come, Lord Jesus!`,
    kjv:`He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus.`,
    greek:`Ναί, ἔρχομαι ταχύ. Ἀμήν, ἔρχου κύριε Ἰησοῦ.`, gk:`the Greek form of the early Aramaic prayer "Maranatha" (1 Corinthians 16:22)`},
  lit:`Christ could return at any moment. "Soon" is measured by God's clock (2 Peter 3:8), and every generation must be ready.`,
  sym:`The book ends as it began, as a letter to be read aloud in church (1:3; 22:16). Its goal is not a calendar but faithfulness: "Blessed is the one who keeps the words" (22:7).`,
  views:{P:`"Near" meant near for the first readers, and much of the book came true in AD 70.`,
    H:`The whole of history from John's day to ours fits inside the book.`,
    F:`The return is imminent, and the warnings are for the last generation.`,
    I:`Every generation lives "near" the end and should live ready.`},
  words:['washrobes','bookoflife'],
  echoes:'Daniel 12:4 · Isaiah 44:6 · Isaiah 11:1, 10 · Numbers 24:17 · Deuteronomy 4:2 · Isaiah 55:1'
}
];

